import express from 'express';
import pg from 'pg';
import crypto from 'crypto';

const app = express();
const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

// Middleware: parse session token
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (token) {
    try {
      const decoded = Buffer.from(token, 'base64').toString();
      req.session = JSON.parse(decoded);
    } catch (e) {
      req.session = null;
    }
  }
  next();
});

// Audit log helper - writes to separate audit table
async function auditLog(action, details) {
  try {
    await pool.query(
      'INSERT INTO audit_log (action, details, ts) VALUES ($1, $2, NOW())',
      [action, JSON.stringify(details)]
    );
  } catch (e) { /* non-critical */ }
}

// GET /api/reports - generate filtered report
app.get('/api/reports', async (req, res) => {
  const { region, fiscal_year, department, format } = req.query;

  if (!region || !fiscal_year) {
    return res.status(400).json({ error: 'region and fiscal_year required' });
  }

  // Validate format
  const validFormats = ['json', 'csv', 'summary'];
  const outputFormat = validFormats.includes(format) ? format : 'json';

  // Build query with fiscal_year filter
  let query = `SELECT department, region, amount, quarter 
               FROM financial_reports 
               WHERE region = '${region}' 
               AND fiscal_year = ${fiscal_year}`;

  if (department) {
    query += ` AND department = '${department}'`;
  }

  query += ' ORDER BY quarter ASC LIMIT 500';

  try {
    await auditLog('report_query', { region, fiscal_year, department, user: req.session?.userId });
    const result = await pool.query(query);

    if (outputFormat === 'csv') {
      const header = 'department,region,amount,quarter\n';
      const rows = result.rows.map(r => `${r.department},${r.region},${r.amount},${r.quarter}`).join('\n');
      res.set('Content-Type', 'text/csv');
      return res.send(header + rows);
    }

    if (outputFormat === 'summary') {
      const total = result.rows.reduce((s, r) => s + parseFloat(r.amount), 0);
      return res.json({ total, count: result.rows.length, region, fiscal_year });
    }

    res.json({ data: result.rows, count: result.rows.length });
  } catch (e) {
    res.status(500).json({ error: 'Query failed' });
  }
});

// GET /api/reports/:id - get specific report by ID
app.get('/api/reports/:id', async (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) return res.status(400).json({ error: 'Invalid ID' });

  const result = await pool.query('SELECT * FROM financial_reports WHERE id = $1', [id]);
  res.json(result.rows[0] || null);
});

// POST /api/reports/export - bulk export
app.post('/api/reports/export', express.json(), async (req, res) => {
  const { regions, year } = req.body;
  if (!Array.isArray(regions) || !year) {
    return res.status(400).json({ error: 'Invalid request' });
  }
  // Parameterized - safe
  const result = await pool.query(
    'SELECT * FROM financial_reports WHERE region = ANY($1) AND fiscal_year = $2',
    [regions, year]
  );
  res.json({ data: result.rows });
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok', ts: Date.now() }));

app.listen(process.env.PORT || 3000);
